import json
import re
from pathlib import Path

from fastapi import APIRouter, Depends, HTTPException
from sqlalchemy.orm import Session

from database import get_db
import runners.evaluation as evaluation


router = APIRouter(prefix="/evaluations", tags=["Evaluations"])

# Restrict IDs to safe filenames generated by the evaluation runner.
EVALUATION_ID_PATTERN = re.compile(
    r"^agent-\d+-[0-9TZ._-]+$"
)


@router.post("/{agent_id}")
async def run_agent_evaluation(
    agent_id: int,
    db: Session = Depends(get_db),
):
    try:
        return await evaluation.evaluate_agent(db, agent_id)

    except ValueError as exc:
        message = str(exc)

        if "was not found" in message:
            raise HTTPException(status_code=404, detail=message)

        raise HTTPException(status_code=422, detail=message)


@router.get("/agent/{agent_id}")
def list_agent_evaluations(
    agent_id: int,
    db: Session = Depends(get_db),
):
    from agents.models import Agent

    agent = db.query(Agent).filter(Agent.id == agent_id).first()

    if agent is None:
        raise HTTPException(
            status_code=404,
            detail="Agent not found",
        )

    reports_dir = Path(evaluation.REPORTS_DIR)

    if not reports_dir.exists():
        return []

    reports = []

    for report_path in reports_dir.glob("*.json"):
        try:
            with report_path.open("r", encoding="utf-8") as file:
                report = json.load(file)

            report_agent = report.get("agent", {})

            if int(report_agent.get("id", -1)) == agent_id:
                reports.append(report)

        except (OSError, json.JSONDecodeError, TypeError, ValueError):
            continue

    reports.sort(
        key=lambda item: item.get("evaluated_at", ""),
        reverse=True,
    )

    return reports


@router.get("/{evaluation_id}")
def get_evaluation_report(evaluation_id: str):
    if not EVALUATION_ID_PATTERN.fullmatch(evaluation_id):
        raise HTTPException(
            status_code=400,
            detail="Invalid evaluation ID",
        )

    report_path = Path(evaluation.REPORTS_DIR) / f"{evaluation_id}.json"

    if not report_path.is_file():
        raise HTTPException(
            status_code=404,
            detail="Evaluation report not found",
        )

    try:
        with report_path.open("r", encoding="utf-8") as file:
            return json.load(file)

    except (OSError, json.JSONDecodeError):
        raise HTTPException(
            status_code=500,
            detail="Unable to read evaluation report",
        )
